from collections import defaultdict
import itertools, math
names=list(pieces)
def shifted(S,d): return {(r+d[0],c+d[1]) for r,c in S}
def pairopts(a,b):
 A,B=pieces[a],pieces[b]; out=[]
 for ma in A['mark']:
  for mb in B['mark']:
   d=(ma[0]-mb[0],ma[1]-mb[1]) # translation b relative a so mb+d=ma
   shared=shifted(B['mark'],d)&set(A['mark'])
   if not shared: continue
   if shifted(B['pix'],d)&set(A['pix']): continue
   out.append((d,len(shared),shared))
 # unique d
 dd={x[0]:x for x in out}
 return sorted(dd.values(),key=lambda x:-x[1])
for a,b in itertools.combinations(names,2):
 o=pairopts(a,b)
 print(a,b,[(d,n) for d,n,_ in o])

trans={'8':(0,0),'5':(-5,-7),'6':(15,-10),'4':(11,-4),'9':(4,-13),'1':(25,3)}
for a,b in [('8','5'),('5','6'),('6','4'),('4','9'),('9','1')]:
 d=(trans[b][0]-trans[a][0],trans[b][1]-trans[a][1]); shared=shifted(pieces[b]['mark'],d)&set(pieces[a]['mark']); print(a,b,d,len(shared),shared)
allpix={}; allmarks=set()
for k,p in pieces.items():
 ps=shifted(p['pix'],trans[k]); collisions=set(ps)&set(allpix)
 if collisions: print('COLLISION',k,collisions)
 for q in ps: allpix[q]=k
 allmarks|=shifted(p['mark'],trans[k])
coords=list(allpix)+list(allmarks)
(min(r for r,c in coords),max(r for r,c in coords),min(c for r,c in coords),max(c for r,c in coords)),len(allmarks)

finalt={'4':(0,0),'6':(4,-6),'5':(-16,-3),'8':(-11,4),'9':(-7,-9),'1':(14,7)}
colorat={}; markowners=defaultdict(list)
for k,p in pieces.items():
 for q in shifted(p['pix'],finalt[k]):
  if q in colorat: print('pixel collision',q,k,colorat[q])
  colorat[q]=k
 for q in shifted(p['mark'],finalt[k]): markowners[q].append(k)
print('markers overlapping pixels',[(q,owners,colorat[q]) for q,owners in markowners.items() if q in colorat])
print('bbox pix',min(r for r,c in colorat),max(r for r,c in colorat),min(c for r,c in colorat),max(c for r,c in colorat))
print('markers',len(markowners), 'multi',[(q,o) for q,o in markowners.items() if len(o)>1])

grid=[[0]*26 for _ in range(26)]
for k,p in pieces.items():
 dr,dc=finalt[k]
 for r,c in p['pix']:
  rr,cc=r+dr,c+dc
  if not (0<=rr<26 and 0<=cc<26): print('out pixel',k,rr,cc)
