 for r,c in p['mark']:
  rr,cc=r+dr,c+dc
  if not (0<=rr<26 and 0<=cc<26): print('out marker',k,rr,cc)
  grid[rr][cc]=2
print('\n'.join(' '.join(map(str,row)) for row in grid))

